INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Turkey';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Dual model — centralized clearance (e-Fatura) or post-issuance reporting (e-Arşiv), both routed through the Revenue Administration (GİB)', 'This deep-dive page reflects publicly available GİB guidance and industry reporting as of August 2026 and is provided for general awareness, not legal or tax advice. Threshold amounts are inflation-indexed and change annually — confirm current figures directly with the Revenue Administration (GİB) or your integration provider before building against them.', 'Turkey''s e-invoicing framework is the most mature in this tracker outside South Korea: e-Fatura became mandatory for larger taxpayers on 1 April 2014, building on e-Transformation groundwork the Revenue Administration (GİB) had been laying since 2012. e-Defter (electronic ledgers) followed in 2015, e-İrsaliye (electronic waybills) in 2023, and the mandate continues to tighten in 2026 with a lower general threshold and the removal of e-Arşiv''s monetary floor entirely.', 'Invoices are authored as structured XML in UBL-TR format and digitally signed. Which of Turkey''s two parallel e-document systems applies — e-Fatura or e-Arşiv — depends on whether the recipient is itself registered for e-Fatura, not on the seller''s own choice.', 'Turkey''s mandate is revenue-threshold based rather than universal, but the thresholds have fallen steadily since 2014 and several sectors are in scope regardless of size.', 'Getting compliant means checking your turnover against the current e-Fatura and e-İrsaliye thresholds, confirming every invoice below those thresholds is still issued as an e-Arşiv invoice, and choosing an access route — GİB''s own portal, a private integrator (özel entegratör), or a direct in-house integration.', 'Turkey enforces e-invoicing compliance through the Tax Procedure Law''s (Vergi Usul Kanunu) special irregularity fines, calculated as a percentage of the invoice value with an inflation-indexed minimum — applied to both the issuer and, unusually among this tracker''s countries, the recipient who accepts a non-compliant invoice.', 'Turkey''s e-Fatura mandate has been in force since 1 April 2014, one of the longest-running e-invoicing regimes this tracker covers, and continues to tighten: e-İrsaliye (e-Waybill) joined the framework in 2023, and from January 2026 the e-Arşiv monetary floor was removed entirely, alongside a lower general e-Fatura threshold.', '🇹🇷' FROM countries WHERE name_en = 'Turkey';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Turkey';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2014', 'e-Fatura mandatory since');
